cypress_script:
describe('Date Picker Functionality', () => {
  it('should successfully select a date', () => {
    cy.visit('https://demoqa.com/date-picker');
    cy.get('#datePickerMonthYearInput').clear().type('12/25/2023');
    cy.get('#datePickerMonthYearInput').should('have.value', '12/25/2023');
  });

  it('should not change when invalid date is input', () => {
    cy.visit('https://demoqa.com/date-picker');
    cy.get('#datePickerMonthYearInput').clear().type('invalid-date');
    cy.get('#datePickerMonthYearInput').should('have.value', '');
    cy.url().should('eq', 'https://demoqa.com/date-picker');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Date Picker Functionality', () => {
  test('should successfully select a date', async ({ page }) => {
    await page.goto('https://demoqa.com/date-picker');
    await page.fill('#datePickerMonthYearInput', '12/25/2023');
    const value = await page.inputValue('#datePickerMonthYearInput');
    expect(value).toBe('12/25/2023');
  });

  test('should not change when invalid date is input', async ({ page }) => {
    await page.goto('https://demoqa.com/date-picker');
    await page.fill('#datePickerMonthYearInput', 'invalid-date');
    const value = await page.inputValue('#datePickerMonthYearInput');
    expect(value).toBe('');
    expect(page.url()).toBe('https://demoqa.com/date-picker');
  });
});
